1	<#
2	.SYNOPSIS
3	  Calcula el siguiente id SDD libre (task/patch) para un proyecto en modo ids.mode=sequence.
4	.DESCRIPTION
5	  Forma parte del kit SDD (skill sdd-templates). No se copia al proyecto: se ejecuta desde el kit con -ProjectRoot.
6	  Solo lee: no crea carpetas ni ficheros, no toca el roadmap, no crea ramas ni contacta con el remoto.
7	.EXAMPLE
8	  pwsh -NoProfile -File Get-NextSddId.ps1 -ProjectRoot D:\code\git\mi-proyecto
9	#>
10	[CmdletBinding()]
11	param(
12	  [string]$ProjectRoot = '.'
13	)
14	$ErrorActionPreference = 'Stop'
15	
16	function Get-EffectiveIdsMode([string]$ProjectRoot) {
17	  $configPath = Join-Path $ProjectRoot '.docs/sdd/sdd-kit.json'
18	  if (-not (Test-Path -LiteralPath $configPath)) { return 'tracker' }
19	  $config = Get-Content -LiteralPath $configPath -Raw | ConvertFrom-Json
20	  $mode = $config.ids.mode
21	  if (@('tracker', 'sequence') -notcontains $mode) { return 'tracker' }
22	  return $mode
23	}
24	
25	function Get-SpecArtifactIds([string]$ProjectRoot) {
26	  $specsPath = Join-Path $ProjectRoot '.docs/sdd/specs'
27	  if (-not (Test-Path -LiteralPath $specsPath)) { return @() }
28	  $folders = Get-ChildItem -LiteralPath $specsPath -Directory
29	  foreach ($folder in $folders) {
30	    if ($folder.Name -match '-(?:task|patch)-(\d{4})[a-z]*-') {
31	      [pscustomobject]@{ Id = $Matches[1]; Folder = $folder.Name }
32	    }
33	  }
34	}
35	
36	function Get-RoadmapIds([string]$ProjectRoot) {
37	  $roadmapPath = Join-Path $ProjectRoot '.docs/sdd/roadmap.md'
38	  if (-not (Test-Path -LiteralPath $roadmapPath)) { return @() }
39	  $lines = Get-Content -LiteralPath $roadmapPath
40	  foreach ($line in $lines) {
41	    if ($line -match '^\|\s*(\d{4})\s*\|') { $Matches[1] }
42	  }
43	}
44	
45	$script:GitEnvVars = @('GIT_DIR', 'GIT_WORK_TREE', 'GIT_INDEX_FILE', 'GIT_COMMON_DIR')
46	
47	function Invoke-IsolatedGit([string]$ProjectRoot, [string[]]$Arguments) {
48	  $saved = @{}
49	  foreach ($name in $script:GitEnvVars) {
50	    $saved[$name] = [System.Environment]::GetEnvironmentVariable($name)
51	    Remove-Item "Env:\$name" -ErrorAction SilentlyContinue
52	  }
53	  try {
54	    return & git -C $ProjectRoot @Arguments 2>$null
55	  }
56	  finally {
57	    foreach ($name in $script:GitEnvVars) {
58	      if ($null -ne $saved[$name]) { Set-Item "Env:\$name" $saved[$name] }
59	    }
60	  }
61	}
62	
63	function Get-RepoToplevel([string]$ProjectRoot) {
64	  $topLevel = Invoke-IsolatedGit $ProjectRoot @('rev-parse', '--show-toplevel')
65	  if ($LASTEXITCODE -ne 0) { return $null }
66	  return (Resolve-Path -LiteralPath ($topLevel -replace '/', '\')).Path.TrimEnd('\')
67	}
68	
69	function Get-BranchIds([string]$ProjectRoot) {
70	  $topLevel = Get-RepoToplevel $ProjectRoot
71	  if ($null -eq $topLevel) { return @() }
72	  if ($topLevel -ine $ProjectRoot.TrimEnd('\')) {
73	    Write-Error "Se omiten las ramas: la raíz del proyecto no es la raíz del repositorio (repositorio en '$topLevel')." -ErrorAction Continue
74	    return @()
75	  }
76	  $branches = Invoke-IsolatedGit $ProjectRoot @('branch', '--all', '--format=%(refname:short)')
77	  foreach ($branch in $branches) {
78	    if ($branch -match '(?:^|/)(\d{4})(?:$|-)') { $Matches[1] }
79	  }
80	}
81	
82	function Assert-NoSharedIds([object[]]$SpecArtifacts) {
83	  foreach ($group in ($SpecArtifacts | Group-Object Id)) {
84	    $folders = $group.Group.Folder | Select-Object -Unique
85	    if ($folders.Count -gt 1) {
86	      throw "Dos artefactos distintos comparten el id $($group.Name): $($folders -join ', ')."
87	    }
88	  }
89	}
90	
91	function Get-NextSddId([string]$ProjectRoot) {
92	  $mode = Get-EffectiveIdsMode $ProjectRoot
93	  if ($mode -ne 'sequence') {
94	    throw "El proyecto no está en modo 'sequence' (modo actual: '$mode'); asigna el id con el gestor de tickets, no con este script."
95	  }
96	  $specArtifacts = @(Get-SpecArtifactIds $ProjectRoot | Where-Object { $_.Id -ne '0000' })
97	  Assert-NoSharedIds $specArtifacts
98	  $allIds = @($specArtifacts.Id) + @(Get-RoadmapIds $ProjectRoot) + @(Get-BranchIds $ProjectRoot)
99	  $usedIds = @($allIds | Where-Object { $_ -ne '0000' } | ForEach-Object { [int]$_ })
100	  $max = if ($usedIds.Count -gt 0) { [int]($usedIds | Measure-Object -Maximum).Maximum } else { 0 }
101	  return '{0:D4}' -f ($max + 1)
102	}
103	
104	if (-not (Test-Path -LiteralPath $ProjectRoot)) {
105	  throw "No existe la ruta de proyecto '$ProjectRoot'."
106	}
107	$ProjectRoot = (Resolve-Path -LiteralPath $ProjectRoot).Path
108	Write-Output (Get-NextSddId $ProjectRoot)
